provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "primary" {
  name = "example.com"
  comment = "Primary Route 53 zone for query logging"
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name = "aws_route53_example_com"
  retention_in_days = 14
  tags = {
    Environment = "production"
    Purpose    = "Route53QueryLogging"
  }
}

resource "aws_cloudwatch_log_resource_policy" "route53-query-logging-policy" {
  policy_name = "route53-query-logging-policy"
  policy_document = jsonencode({
    "Version" = "2012-10-17"
    "Statement" = [{
      "Effect"     = "Allow"
      "Principal"  = { "Service" = "route53.amazonaws.com" }
      "Action"     = "logs:PutLogEvents"
      "Resource"   = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:aws_route53_example_com:*"
    }]
  })
}

resource "aws_route53_query_logging_config" "primary_query_logging" {
  zone_id = aws_route53_zone.primary.zone_id
  log_group_name = aws_cloudwatch_log_group.aws_route53_example_com.name
  depends_on = [
    aws_cloudwatch_log_group.aws_route53_example_com,
    aws_cloudwatch_log_resource_policy.route53-query-logging-policy
  ]
}
```

