provider "aws" {
  region = "us-east-1"
}

# Create a Route 53 hosted zone (assuming it already exists or is known)
resource "aws_route53_zone" "primary" {
  name = "primary"
}

# Create an Elastic Load Balancer
resource "aws_elb" "main" {
  name = "main"
  subnets = ["subnet-12345678"]  # Example subnet ID, replace with actual subnet
  security_groups = ["sg-12345678"]  # Example security group ID, replace with actual SG

  listener {
    lb_port        = 80
    lb_protocol    = "http"
    instance_port  = 80
    instance_protocol = "http"
  }

  access_logs {
    bucket = "my-loadbalancer-logs"
    bucket_prefix = "elb-logs"
    enabled = true
    interval = 60
  }

  health_check {
    healthy_threshold = 3
    unhealthy_threshold = 3
    target = "HTTP:80/"
    interval = 30
    timeout = 5
  }

  tags = {
    Name = "main-elb"
  }
}

# Create a Route 53 record pointing to the ELB's DNS name
resource "aws_route53_record" "primary_elb_record" {
  name    = "main.elb.primary"
  zone_id = aws_route53_zone.primary.id
  type    = "A"
  ttl     = 300
  records = [aws_elb.main.dns_name]
}
```

