resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Create S3 bucket for object storage
resource "aws_s3_bucket" "examplebucket" {
  bucket = "examplebucket-${random_string.unique_name.result}"
  acl = "private"
  force_destroy = true
  tags = {
    Terraform = "true"
    Environment = "production"
  }
}

# Create S3 object in the bucket
resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.examplebucket.bucket
  key = "example-object.txt"
  content = "This is an example object in the S3 bucket."
}

# Create Elastic Beanstalk application
resource "aws_elasticbeanstalk_application" "myapp" {
  name = "myapp"
  description = "My Elastic Beanstalk application"
}

# Create Elastic Beanstalk environment
resource "aws_elasticbeanstalk_environment" "eb-env" {
  name = "eb-env"
  application = aws_elasticbeanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2 v4.0.0 running Python 3.9"
  instance_profile_arn = aws_iam_instance_profile.eb_ec2_profile.arn
  environment_type = "LoadBalanced"
  tier = "WebServer"
  cname = "myapp.example.com"
  tags = {
    Terraform = "true"
    Environment = "production"
  }
}

# Create Elastic Beanstalk application version
resource "aws_elasticbeanstalk_application_version" "version" {
  application = aws_elasticbeanstalk_application.myapp.name
  version_label = "version"
  source_bundle {
    s3_bucket = aws_s3_bucket.examplebucket.bucket
    s3_key = aws_s3_object.examplebucket_object.key
  }
}

# Generate a unique name for the S3 bucket
resource "random_string" "unique_name" {
  length = 8
  special = false
}
