provider "aws" {
  region = "us-west-2"
}

# Define the IAM role for EC2 instances in the Elastic Beanstalk environment
resource "aws_iam_role" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Create the relational database instance
resource "aws_db_instance" "default" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "8.0.33"
  username = "admin"
  password = "securepassword123"
  db_name = "mydb"
  backup_retention_period = 7
  skip_final_snapshot = true
  storage_type = "gp2"
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  tags = {
    Name = "default-db"
  }
}

# Create a security group for the database instance
resource "aws_security_group" "db_sg" {
  name = "db_sg"
  description = "Allow access to database"
  vpc_id = aws_vpc.default.id

  ingress {
    from_port = 3306
    to_port = 3306
    protocol = "tcp"
    cidr_blocks = ["172.16.0.0/16"]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a VPC for the infrastructure
resource "aws_vpc" "default" {
  cidr_block = "172.16.0.0/16"
  tags = {
    Name = "default-vpc"
  }
}

# Create a subnet for the VPC
resource "aws_subnet" "default" {
  vpc_id = aws_vpc.default.id
  cidr_block = "172.16.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "default-subnet"
  }
}

# Create a route table for the VPC
resource "aws_route_table" "default" {
  vpc_id = aws_vpc.default.id
  tags = {
    Name = "default-route-table"
  }
}

# Associate the subnet with the route table
resource "aws_route_table_association" "default" {
  subnet_id = aws_subnet.default.id
  route_table_id = aws_route_table.default.id
}

# Create an Elastic Beanstalk environment
resource "aws_elasticbeanstalk_environment" "eb_env" {
  name = "eb_env"
  application = "my-app"
  solution_stack_name = "64bit Amazon Linux 2 v4.12.0 running Python 3.10"
  environment_type = "load-balanced"
  tier = "Production"
  cname = "myapp-env.elasticbeanstalk.us-west-2.amazonaws.com"
  description = "Elastic Beanstalk environment for my app"
  tags = {
    Environment = "Production"
  }

  # Link the environment to the database instance
  database = {
    db_instance_identifier = aws_db_instance.default.id
    db_password = aws_db_instance.default.password
    db_user = aws_db_instance.default.username
    db_name = aws_db_instance.default.db_name
    db_host = aws_db_instance.default.address
    db_port = 3306
  }

  # IAM role for EC2 instances
  iam_role = aws_iam_role.eb_ec2_profile.name
}
