    delete = "1h"
  }
}

# Create RDS Cluster Instance
resource "aws_rds_cluster_instance" "my_db1_instance" {
  cluster_identifier = aws_rds_cluster.my_db1.id
  instance_class     = "db.r4.large"
  db_subnet_group_name = "default"
  copy_tags_to_snapshot = true
  tags = {
    Name = "my_db1_instance"
  }
  timeouts {
    create = "1h"
    delete = "1h"
  }
}

# Create IAM Role for EC2 instances
resource "aws_iam_role" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach RDS policy to the IAM role
resource "aws_iam_role_policy_attachment" "eb_ec2_profile_attach_rds" {
  role       = aws_iam_role.eb_ec2_profile.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

# Create Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "eb_env" {
  application = "my_app"
  name        = "eb_env"
  tier        = "Worker"
  solution_stack_name = "64bit Amazon Linux 2 v3.4.0 running Python 3.9"
  environment_name = "eb_env"
  description = "Elastic Beanstalk environment with autoscaling and RDS integration"
  cname_prefix = "myapp"
  platform_arn = "arn:aws:elasticbeanstalk:us-west-2::platform/Python 3.9 running on 64bit Amazon Linux 2/3.4.0"
  tags = {
    Environment = "Production"
  }
  setting {
    name  = "aws:rds:db:dbInstanceIdentifier"
    value = "my_db1_instance"
    namespace = "aws:rds:db"
  }
  setting {
    name  = "aws:rds:db:dbPassword"
    value = "password"
    namespace = "aws:rds:db"
  }
  setting {
    name  = "aws:rds:db:dbUsername"
    value = "admin"
    namespace = "aws:rds:db"
  }
  setting {
    name  = "aws:rds:db:dbPort"
    value = "3306"
    namespace = "aws:rds:db"
  }
  setting {
    name  = "aws:rds:db:dbSubnetGroupName"
    value = "default"
    namespace = "aws:rds:db"
  }
  setting {
    name  = "aws:rds:db:dbSecurityGroupNames"
    value = "default"
    namespace = "aws:rds:db"
  }
}

# Create Autoscaling Group
resource "aws_autoscaling_group" "eb_asg" {
  name = "eb_asg"
  max_size = 2
  min_size = 1
  desired_capacity = 1
  availability_zones = ["us-west-2a", "us-west-2b", "us-west-2c"]
  launch_template {
    id = "launch-template-1"
    version = "$Latest"
  }
  health_check_grace_period = 300
  health_check_type = "EC2"
  tag {
    key                 = "Environment"
    value               = "Production"
    propagate_at_launch = true
  }
  tag {
    key                 = "Name"
    value               = "eb_asg"
    propagate_at_launch = true
  }
  timeouts {
    create = "1h"
    delete = "1h"
  }
}

# Create Autoscaling Policy based on CPU utilization
resource "aws_autoscaling_policy" "eb_asg_cpu_scaling_policy" {
  name = "eb_asg_cpu_scaling_policy"
  autoscaling_group_name = aws_autoscaling_group.eb_asg.name
  policy_type = "TargetTrackingScaling"
  target_tracking_configuration {
    target_value = 70
    predefined_metric_specification {
      predefined_metric_type = "CPUUtilization"
    }
  }
  cooldown = 300
  enabled = true
}
