  description = "The GitHub owner of the repository"
  default     = "example-user"
}

variable "github_branch" {
  description = "The branch to build"
  default     = "main"
}

variable "codebuild_project_name" {
  description = "Name of the CodeBuild project"
  default     = "example-codebuild-project"
}

variable "environment_variables" {
  description = "Environment variables for the CodeBuild project"
  default     = {
    "ENV_VAR_1" = "value1"
    "ENV_VAR_2" = "value2"
  }
}

variable "cache_location" {
  description = "S3 bucket location for CodeBuild cache"
  default     = "s3://example-codebuild-cache-bucket"
}

variable "cache_modes" {
  description = "Cache modes for CodeBuild"
  default     = ["LOCAL"]
}

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role-${var.codebuild_project_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "codebuild.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_role_attachment" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildRole"
}

resource "aws_codebuild_project" "codebuild_project" {
  name = var.codebuild_project_name

  service_role = aws_iam_role.codebuild_role.arn

  source {
    type = "GITHUB"
    location = var.github_repository
    git_clone_depth = 1
    report_build_status = true
    buildspec = "buildspec.yml"
  }

  environment {
    type = "LINUX_CONTAINER"
    image = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    compute_type = "BUILD_GENERAL1_SMALL"
    privileged_mode = false
    image_pull_credentials_type = "CODEBUILD"
  }

  cache {
    type = "S3"
    location = var.cache_location
    modes = var.cache_modes
  }

  environment_variables = jsonencode(var.environment_variables)

  tags = {
    Terraform = "true"
    Environment = "dev"
  }
}
