variable "node_group_instance_types" {
  description = "List of instance types for the EKS node group."
  type        = list(string)
  default     = ["t3.micro"]
}

variable "node_group_desired_size" {
  description = "Desired size of the EKS node group."
  type        = number
  default     = 2
}

variable "node_group_max_size" {
  description = "Maximum size of the EKS node group."
  type        = number
  default     = 4
}

variable "node_group_min_size" {
  description = "Minimum size of the EKS node group."
  type        = number
  default     = 2
}

variable "eks_addon_name" {
  description = "Name of the EKS addon."
  type        = string
  default     = "vpc-cni"
}

variable "eks_addon_version" {
  description = "Version of the EKS addon."
  type        = string
  default     = "1.3.0"
}

resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "eks.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_iam_role_policy_attachment" "eks_service_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_eks_cluster" "eks_cluster" {
  name = var.cluster_name
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = var.vpc_subnet_ids
  }

  kubernetes_network_config {
    ip_family = "ipv4"
    service_ipv4_cidr = "172.20.0.0/16"
  }

  version = "1.28"
}

resource "aws_eks_node_group" "eks_node_group" {
  cluster_name = var.cluster_name
  node_role_arn = aws_iam_role.eks_cluster_role.arn
  subnet_ids = var.vpc_subnet_ids

  launch_template {
    name = "eks-node-launch-template"
    version = "1"
  }

  scaling_config {
    desired_size = var.node_group_desired_size
    max_size = var.node_group_max_size
    min_size = var.node_group_min_size
  }

  instance_types = var.node_group_instance_types
  ami_type = "AL2_x86_64"
  labels = {
    "Environment" = "Production"
  }
}

resource "aws_eks_addon" "eks_addon" {
  cluster_name = var.cluster_name
  addon_name = var.eks_addon_name
  addon_version = var.eks_addon_version
}

resource "null_resource" "kubectl_config_provisioner" {
  depends_on = [aws_eks_cluster.eks_cluster]

  provisioner "local-exec" {
    command = "aws eks update-kubeconfig --name ${var.cluster_name} --region us-west-2"
  }

  provisioner "local-exec" {
    when    = "destroy"
    command = "aws eks delete-kubeconfig --name ${var.cluster_name} --region us-west-2"
  }
}
