  default     = "my-eks-cluster"
}

variable "eks_fargate_subnets" {
  description = "List of subnet IDs for EKS Fargate profile"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "eks_vpc_id" {
  description = "VPC ID where the EKS cluster and subnets reside"
  default     = "vpc-12345678"
}

variable "eks_fargate_profile_name" {
  description = "Name of the EKS Fargate profile"
  default     = "eks-fargate-profile-kube-system"
}

variable "eks_fargate_pod_execution_role_name" {
  description = "Name of the IAM role for EKS Fargate pod execution"
  default     = "eks-fargate-pod-execution-role"
}

variable "eks_cluster_endpoint" {
  description = "Endpoint of the EKS cluster"
  default     = "https://api.my-eks-cluster.us-west-2.eks.amazonaws.com"
}

variable "eks_cluster_certificate_authority_data" {
  description = "Certificate authority data for the EKS cluster"
  default     = "LS0tLS1CRUdJTiBDRVJUSUZJQ0FURS0tLS0t"
}

variable "eks_cluster_token" {
  description = "Authentication token for the EKS cluster"
  default     = "xxxxx"
}

resource "aws_iam_role" "eks_fargate_pod_execution_role" {
  name = var.eks_fargate_pod_execution_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "eks-fargate-pod.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_fargate_pod_execution_role_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSFargatePodExecutionRolePolicy"
  role       = aws_iam_role.eks_fargate_pod_execution_role.name
}

resource "aws_subnet" "eks_fargate_subnets" {
  count = length(var.eks_fargate_subnets) > 0 ? length(var.eks_fargate_subnets) : 0

  vpc_id                  = var.eks_vpc_id
  cidr_block              = var.eks_fargate_subnets[count.index]
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
}

resource "aws_resource_tag" "eks_fargate_subnet_tag" {
  resource_arn = aws_subnet.eks_fargate_subnets[0].arn
  tag_key      = "kubernetes.io/cluster/${var.eks_cluster_name}"
  tag_value    = "owned"
}

resource "aws_eks_fargate_profile" "eks_fargate_profile_kube_system" {
  cluster_name           = var.eks_cluster_name
  fargate_profile_name   = var.eks_fargate_profile_name
  pod_execution_role_arn = aws_iam_role.eks_fargate_pod_execution_role.arn
  subnet_ids             = var.eks_fargate_subnets

  selector {
    namespace = "kube-system"
  }

  tags = {
    Name = "eks-fargate-profile-kube-system"
  }
}

resource "null_resource" "patch_coredns_deployment" {
  depends_on = [aws_eks_fargate_profile.eks_fargate_profile_kube_system]

  provisioner "local-exec" {
    command = <<EOT
      kubectl apply -f - <<EOF
      apiVersion: apps/v1
      kind: Deployment
      metadata:
        name: coredns
        namespace: kube-system
        annotations:
          eks.amazonaws.com/fargate: "true"
      spec:
        replicas: 1
        selector:
          matchLabels:
            k8s-app: coredns
        template:
          metadata:
            labels:
              k8s-app: coredns
          spec:
            containers:
            - name: coredns
              image: coredns/coredns:1.10.0
              args:
              - -conf
              - /etc/coredns/Corefile
              volumeMounts:
              - name: config
                mountPath: /etc/coredns
                readOnly: true
            volumes:
            - name: config
              configMap:
                name: coredns
            imagePullSecrets:
            - name: eks-registry
            nodeSelector:
              eks.amazonaws.com/fargate: "true"
            tolerations:
            - key: eks.amazonaws.com/fargate
              operator: Exists
              effect: NoSchedule
      EOF
    EOT
  }
}
