provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "mybucket" {
  bucket = "mybucket"
  acl    = "private"

  # Enable versioning
  versioning {
    enabled = true
  }

  # Object lock configuration for compliance mode
  object_lock_configuration {
    object_lock_enabled = true
    rule {
      default_retention {
        mode    = "COMPLIANCE"
        days    = 5
        mode    = "COMPLIANCE"
      }
    }
  }

  # Optional: Add CORS configuration if needed
  cors_rule {
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
  }

  # Optional: Add tags for organization
  tags = {
    Environment = "production"
    Project    = "myproject"
  }
}

resource "aws_s3_bucket_versioning" "mybucket_versioning" {
  bucket = aws_s3_bucket.mybucket.bucket
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_object_lock_configuration" "mybucket_object_lock" {
  bucket = aws_s3_bucket.mybucket.bucket
  rule {
    default_retention {
      mode    = "COMPLIANCE"
      days    = 5
    }
  }
}
