resource "aws_kms_key" "kms_key" {
  description             = var.kms_key_description
  deletion_window_in_days = 7
  key_usage               = "ENCRYPT_DECRYPT"
  policy                  = jsonencode({
    Version   = "2012-10-17"
    Statement = [{
      Sid       = "Enable IAM User Permissions"
      Effect    = "Allow"
      Principal = { AWS = "arn:aws:iam::${aws_kms_key.kms_key.account_id}:user/*" }
      Action    = [
        "kms:DescribeKey",
        "kms:GetKeyPolicy",
        "kms:ListKeys",
        "kms:PutKeyPolicy",
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:GenerateDataKey"
      ]
      Resource = "arn:aws:kms:${aws_kms_key.kms_key.region}:${aws_kms_key.kms_key.account_id}:key/${aws_kms_key.kms_key.key_id}"
    }]
  })
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "aws:kms"
