  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy_attachment" "lambda_dynamodb_table_access" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSDynamoDBFullAccess"
}

resource "aws_lambda_function" "lambda_function" {
  function_name    = var.lambda_function_name
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda_function.zip"
  source_code_hash = "base64:example-hash"
  timeout          = 30

  environment {
    variables = {
      DYNAMODB_TABLE_NAME = var.dynamodb_table_name
    }
  }

  vpc_config {
    security_group_ids = ["sg-12345678"]
    subnet_ids         = ["subnet-12345678", "subnet-87654321"]
  }

  tracing_config {
    mode = "Active"
  }

  dead_letter_config {
    target_arn = "arn:aws:sqs:us-east-1:123456789012:dead-letter-queue"
  }

  logging_config {
    log_format = "json"
    log_group  = "/aws/lambda/dynamodb-event-lambda"
  }

  image_config {
    command = ["node", "index.js"]
    entry_point = []
    working_directory = "/"
  }

  snap_start {
    apply_on = "PublishedVersion"
  }

  timeouts {
    create = "5m"
    update = "5m"
    delete = "5m"
  }
}

resource "aws_dynamodb_table" "dynamodb_table" {
  name         = var.dynamodb_table_name
  billing_mode = "PROVISIONED"
  read_capacity = 5
  write_capacity = 5

  attribute {
    name = "id"
    type = "S"
  }

  stream_enabled = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  tags = {
    Environment = "production"
    Project     = "dynamodb-event"
  }

  timeouts {
    create = "5m"
    update = "5m"
    delete = "5m"
  }
}

resource "aws_lambda_event_source_mapping" "lambda_event_source_mapping" {
  function_name             = aws_lambda_function.lambda_function.function_name
  event_source_arn          = aws_dynamodb_table.dynamodb_table.arn
  batch_size                = 100
  enabled                   = true
  starting_position         = "LATEST"
  maximum_batching_window_in_seconds = 60
  maximum_retry_attempts    = 3
  parallelization_factor    = 1

  destination_config {
    onFailure = "arn:aws:sqs:us-east-1:123456789012:error-queue"
  }

  filter_criteria {
    filters = [{
      pattern = "{\"dynamodb\": {\"NewImage\": {\"id\": {\"S\": \"*\"}}}}"
    }]
  }

  metrics_config {
    metrics = ["All"]
  }

  source_access_configuration {
    type = "DynamoDB"
    uri  = "arn:aws:dynamodb:us-east-1:123456789012:table/dynamodb-event-table"
  }

  timeouts {
    create = "5m"
    update = "5m"
    delete = "5m"
  }
}
```

