provider "aws" {
  region = "us-east-1"
}

# Create the kmeans image
resource "aws_sagemaker_image" "kmeans_image" {
  image_name = "kmeans-image"
  role_arn   = aws_iam_role.sagemaker_execution_role.arn
}

# Create an IAM role for SageMaker execution
resource "aws_iam_role" "sagemaker_execution_role" {
  name = "sagemaker_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "sagemaker.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_execution_role_policy" {
  role       = aws_iam_role.sagemaker_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
}

# Create the model package
resource "aws_sagemaker_model_package" "kmeans_model_package" {
  model_package_name = "kmeans-model-package"
  image_uri          = aws_sagemaker_image.kmeans_image.arn
  role_arn           = aws_iam_role.sagemaker_execution_role.arn
  model_package_type = "MlModel"

  model_metrics {
    metric_data {
      name   = "accuracy"
      value = 0.95
    }
  }

  certification_status = "Certified"
  approval_status      = "Approved"
}

# Create the SageMaker model
resource "aws_sagemaker_model" "kmeans_model" {
  name = "kmeans-model"

  execution_role_arn = aws_iam_role.sagemaker_execution_role.arn

  container {
    image = aws_sagemaker_image.kmeans_image.arn
    model_data_url = "s3://my-sagemaker-bucket/model.tar.gz"
    mode = "SingleRecord"
  }

  inference_execution_config {
    mode = "ServeForests"
  }
}
```

