provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
}

resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2a"
}

resource "aws_launch_template" "launch_template" {
  name = "aws-linux2-ec2-fleet"

  image_id              = "ami-0c55b159cbfafe1f0" # AWS Linux 2 AMI (us-west-2)
  instance_type         = "t3.micro"
  key_name              = "my-key-pair" # Default key pair name
  security_group_names  = ["launch-template-sg"]
  iam_instance_profile  = "my-iam-instance-profile" # Default IAM instance profile name

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 20
      volume_type = "gp2"
    }
  }

  instance_initiated_shutdown_behavior = "stop"
  ebs_optimized                       = false
  monitoring {
    enabled = true
  }
}

resource "aws_ec2_fleet" "ec2_fleet" {
  launch_template_config {
    launch_template_id = aws_launch_template.launch_template.id
    version            = "$Latest"
  }

  target_capacity_specification {
    default_target_capacity_type = "spot"
    total_target_capacity        = 9
  }

  on_demand_options {
    allocation_strategy = "prioritizeOnDemand"
    max_total_price     = "0.05"
    min_target_capacity = 5
  }

  spot_options {
    allocation_strategy = "lowestPrice"
    instance_interruption_behavior = "terminate"
    max_total_price     = "0.05"
    min_target_capacity = 4
  }

  replace_unhealthy_instances = true
  terminate_instances        = true
  terminate_instances_with_expiration = true
}
