}

variable "private_subnet_app_cidr" {
  description = "The CIDR block for the private subnet for the application server"
  default     = "10.0.2.0/24"
}

variable "private_subnet_db_cidr" {
  description = "The CIDR block for the private subnet for the relational database"
  default     = "10.0.3.0/24"
}

variable "availability_zones" {
  description = "List of availability zones to use for subnets"
  default     = ["us-west-2a", "us-west-2b", "us-west-2c"]
}

resource "aws_vpc" "vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = var.availability_zones[0]
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private_subnet_app" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = var.private_subnet_app_cidr
  availability_zone       = var.availability_zones[1]
  map_public_ip_on_launch = false
}

resource "aws_subnet" "private_subnet_db" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = var.private_subnet_db_cidr
  availability_zone       = var.availability_zones[2]
  map_public_ip_on_launch = false
}
