```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  default = "mks_cluster"
}

variable "kafka_version" {
  default = "3.6.1"
}

variable "number_of_broker_nodes" {
  default = 3
}

variable "instance_type" {
  default = "t3.micro"
}

variable "client_subnets" {
  default = ["subnet-12345678", "subnet-87654321", "subnet-11122233"]
}

variable "security_groups" {
  default = ["sg-12345678"]
}

variable "az_distribution" {
  default = "DEFAULT"
}

variable "iam_role_name" {
  default = "mks_cluster_role"
}

variable "iam_role_description" {
  default = "IAM role for MSK cluster"
}

variable "iam_role_policy_arn" {
  default = "arn:aws:iam::123456789012:policy/AmazonMSKServiceRolePolicy"
}

resource "aws_iam_role" "mks_cluster_role" {
  name               = var.iam_role_name
  description        = var.iam_role_description
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect  = "Allow"
      Principal = {
        Service = "kafka.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "mks_cluster_role_attachment" {
  role       = aws_iam_role.mks_cluster_role.name
  policy_arn = var.iam_role_policy_arn
}

resource "aws_msk_cluster" "mks_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes
  client_authentication {
    unauthenticated = false
  }
  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-east-1:123456789012:key/abcd1234-a123-4567-8abc-def123456789"
  }
  logging_info {
    cloud_watch {
      enabled = true
    }
  }
  open_monitoring {
    cloud_watch {
      enabled = true
    }
  }
  broker_node_group_info {
    client_subnets        = var.client_subnets
    instance_type         = var.instance_type
    security_groups       = var.security_groups
    az_distribution       = var.az_distribution
  }
  tags = {
    Environment = "production"
  }
}
```

