provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = "msk-logs-bucket"
  acl    = "private"

  # Enable logging to allow MSK to write logs
  logging {
    target_bucket = aws_s3_bucket.s3_bucket.id
    target_prefix = "msk-logs/"
  }

  # Enable versioning to ensure log integrity
  versioning {
    enabled = true
  }

  # Set up a policy to allow MSK to write logs
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { AWS = "arn:aws:iam::aws:root" }
      Action = ["s3:PutObject", "s3:GetBucketAcl", "s3:ListBucket"]
      Resource = [
        "${aws_s3_bucket.s3_bucket.arn}",
        "${aws_s3_bucket.s3_bucket.arn}/*"
      ]
    }]
  })

  tags = {
    Name        = "MSK-Logs-Bucket"
    Environment = "production"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster"
  kafka_version          = "3.6.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets     = ["subnet-12345678", "subnet-87654321"]
    instance_type      = "t3.micro"
    security_groups    = ["sg-12345678"]
    az_distribution    = "DEFAULT"
  }

  logging_info {
    cloud_watch_logs {
      enabled = false
    }
    firehose {
      enabled = false
    }
    s3 {
      enabled = true
      bucket_arn = aws_s3_bucket.s3_bucket.arn
      prefix     = "msk-logs/"
    }
  }

  tags = {
    Name        = "MSK-Cluster"
    Environment = "production"
  }

  timeouts {
    create = "30m"
    delete = "30m"
  }
}
