```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "msk-cluster"
}

variable "firehose_stream_name" {
  description = "Name of the Kinesis Firehose delivery stream"
  default     = "firehose-logs"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket where Firehose will deliver logs"
  default     = "firehose-logs-bucket"
}

variable "iam_role_name" {
  description = "Name of the IAM role for Firehose"
  default     = "firehose-role"
}

variable "iam_policy_name" {
  description = "Name of the IAM policy for Firehose"
  default     = "firehose-policy"
}

variable "kafka_version" {
  description = "Kafka version for the MSK cluster"
  default     = "3.6.1"
}

variable "number_of_broker_nodes" {
  description = "Number of broker nodes for the MSK cluster"
  default     = 3
}

variable "broker_instance_type" {
  description = "Instance type for the MSK brokers"
  default     = "t3.micro"
}

variable "client_subnets" {
  description = "Subnets for the MSK cluster"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "Security group for the MSK cluster"
  default     = "sg-12345678"
}

resource "aws_iam_role" "firehose_role" {
  name               = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "firehose.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "firehose_policy" {
  name        = var.iam_policy_name
  role        = aws_iam_role.firehose_role.name
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "firehose:PutRecord",
        "firehose:PutRecordBatch"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name        = var.firehose_stream_name
  destination = "s3"

  extended_s3_configuration {
    role_arn      = aws_iam_role.firehose_role.arn
    bucket_arn    = "arn:aws:s3:::${var.s3_bucket_name}"
    prefix        = "logs/"
    buffering_interval = 60
    buffering_size    = 10485760
    compression_format = "UNCOMPRESSED"
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name         = var.msk_cluster_name
  kafka_version        = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    client_subnets     = var.client_subnets
    instance_type      = var.broker_instance_type
    security_groups    = [var.security_group_id]
    az_distribution    = "DEFAULT"
  }

  logging_info {
    firehose {
      delivery_stream_arn = aws_kinesis_firehose_delivery_stream.firehose_stream.arn
    }
  }

  tags = {
    Environment = "production"
  }
}
```

