```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the MSK cluster"
  default     = "msk-cluster"
}

variable "kafka_version" {
  description = "Kafka version for the MSK cluster"
  default     = "3.6.1"
}

variable "broker_instance_type" {
  description = "Instance type for the MSK broker nodes"
  default     = "t3.micro"
}

variable "client_subnets" {
  description = "List of client subnets for the MSK cluster"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_groups" {
  description = "List of security groups for the MSK cluster"
  default     = ["sg-12345678"]
}

variable "az_distribution" {
  description = "AZ distribution for the broker nodes"
  default     = "DEFAULT"
}

variable "number_of_broker_nodes" {
  description = "Number of broker nodes in the MSK cluster"
  default     = 3
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_service_role_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKServiceRolePolicy"
  role       = aws_iam_role.msk_service_role.name
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    client_subnets     = var.client_subnets
    instance_type      = var.broker_instance_type
    security_groups    = var.security_groups
    az_distribution    = var.az_distribution
  }

  client_authentication {
    unauthenticated = false
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_msk_broker_node_group_info" "msk_broker_node_group" {
  depends_on = [aws_msk_cluster.msk_cluster]

  client_subnets     = var.client_subnets
  instance_type      = var.broker_instance_type
  security_groups    = var.security_groups
  az_distribution    = var.az_distribution
}
```

