  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role" "msk_cluster_cloudwatch_role" {
  name = var.iam_role_cloudwatch_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "cloudwatch.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_cloudwatch_log_group" "cloudwatch_log_group" {
  name = var.cloudwatch_log_group_name
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"
}

resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name = var.firehose_delivery_stream_name
  destination = "s3"
  destination_id = var.s3_bucket_name

  extended_s3_configuration {
    bucket_arn = aws_s3_bucket.s3_bucket.arn
    role_arn = aws_iam_role.msk_cluster_firehose_role.arn
    prefix = "firehose"
  }
}

resource "aws_msk_cluster" "mks_cluster" {
  cluster_name = var.cluster_name
  kafka_version = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes
  enhanced_monitoring = "DEFAULT"
  storage_mode = "UNLIMITED"

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321", "subnet-11122233"]
    instance_type = "t3.micro"
    security_groups = ["sg-12345678"]
    az_distribution = "DEFAULT"
  }

  client_authentication {
    unauthenticated = true
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-a123-4567-8abc-def123456789"
  }

  logging_info {
    cloudwatch_logs {
      cloudwatch_log_group_arn = aws_cloudwatch_log_group.cloudwatch_log_group.arn
    }
  }

  open_monitoring {
    cloudwatch_metrics {
      dimensions = {
        "ClusterName" = var.cluster_name
      }
    }
  }

  depends_on = [
    aws_iam_role.msk_cluster_role,
    aws_iam_role.msk_cluster_open_monitoring_role,
    aws_iam_role.msk_cluster_encryption_role,
    aws_iam_role.msk_cluster_firehose_role,
    aws_iam_role.msk_cluster_cloudwatch_role
  ]
}
