```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  default = "vpc-12345678"
}

variable "subnet_cidr" {
  default = "10.0.1.0/24"
}

variable "neptune_instance_type" {
  default = "neptune.cluster.amazonaws.com"
}

variable "neptune_engine_version" {
  default = "14.0"
}

variable "neptune_cluster_identifier" {
  default = "my-neptune-cluster"
}

variable "neptune_instance_identifier" {
  default = "my-neptune-instance"
}

variable "neptune_cluster_parameter_group_name" {
  default = "my-neptune-cluster-param-group"
}

variable "neptune_instance_parameter_group_name" {
  default = "my-neptune-instance-param-group"
}

variable "neptune_cluster_parameter" {
  default = {
    "neptune_query_timeout" = "300"
  }
}

variable "neptune_instance_parameter" {
  default = {
    "neptune_query_timeout" = "600"
  }
}

resource "aws_subnet" "example_subnet" {
  vpc_id                  = var.vpc_id
  cidr_block              = var.subnet_cidr
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "neptune_security_group" {
  name        = "neptune-allow-access"
  description = "Allow access to Neptune instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    security_groups = [aws_security_group.neptune_security_group.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group_rule" "neptune_security_group_rule" {
  type              = "ingress"
  protocol          = "tcp"
  from_port         = 8182
  to_port           = 8182
  security_group_id = aws_security_group.neptune_security_group.id
  cidr_blocks       = [aws_subnet.example_subnet.cidr_block]
}

resource "aws_neptune_cluster_parameter_group" "neptune_cluster_parameter_group" {
  name        = var.neptune_cluster_parameter_group_name
  family      = "neptune1"
  description = "Custom parameter group for Neptune cluster"

  parameter {
    name  = "neptune_query_timeout"
    value = var.neptune_cluster_parameter["neptune_query_timeout"]
  }
}

resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier      = var.neptune_cluster_identifier
  engine                  = "neptune"
  engine_version          = var.neptune_engine_version
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.neptune_cluster_parameter_group.name
  availability_zones      = ["us-west-2a", "us-west-2b", "us-west-2c"]
  backup_retention_period = 7
  deletion_protection      = false
}

resource "aws_neptune_instance_parameter_group" "neptune_instance_parameter_group" {
  name        = var.neptune_instance_parameter_group_name
  family      = "neptune1"
  description = "Custom parameter group for Neptune instance"

  parameter {
    name  = "neptune_query_timeout"
    value = var.neptune_instance_parameter["neptune_query_timeout"]
  }
}

resource "aws_neptune_instance" "neptune_instance" {
  cluster_identifier        = aws_neptune_cluster.neptune_cluster.id
  instance_identifier       = var.neptune_instance_identifier
  instance_type             = var.neptune_instance_type
  neptune_instance_parameter_group_name = aws_neptune_instance_parameter_group.neptune_instance_parameter_group.name
  security_group_ids        = [aws_security_group.neptune_security_group.id]
}
```

