provider "aws" {
  region = "us-east-1"
}

variable "chime_voice_connector_name" {
  description = "Name of the Chime Voice Connector"
  default     = "my-voice-connector"
}

variable "chime_voice_connector_group_name" {
  description = "Name of the Chime Voice Connector Group"
  default     = "my-voice-connector-group"
}

variable "chime_voice_connector_termination_calling_regions" {
  description = "List of calling regions for termination"
  default     = ["us-east-1", "us-west-2"]
}

variable "chime_voice_connector_termination_cidr_allow_list" {
  description = "CIDR allow list for termination"
  default     = ["10.0.0.0/16", "192.168.0.0/16"]
}

variable "chime_voice_connector_logging_enable_media_metric_logs" {
  description = "Enable media metric logs"
  default     = true
}

variable "chime_voice_connector_logging_enable_sip_logs" {
  description = "Enable SIP logs"
  default     = false
}

resource "aws_chime_voice_connector" "chime_voice_connector" {
  name             = var.chime_voice_connector_name
  require_encryption = true
}

resource "aws_chime_voice_connector_group" "chime_voice_connector_group" {
  name = var.chime_voice_connector_group_name

  connector {
    priority = 1
    voice_connector_id = aws_chime_voice_connector.chime_voice_connector.id
  }
}

resource "aws_chime_voice_connector_termination" "chime_voice_connector_termination" {
  calling_regions        = var.chime_voice_connector_termination_calling_regions
  cidr_allow_list        = var.chime_voice_connector_termination_cidr_allow_list
  voice_connector_id     = aws_chime_voice_connector.chime_voice_connector.id
}

resource "aws_chime_voice_connector_logging" "chime_voice_connector_logging" {
  voice_connector_id = aws_chime_voice_connector.chime_voice_connector.id
  enable_media_metric_logs = var.chime_voice_connector_logging_enable_media_metric_logs
  enable_sip_logs = var.chime_voice_connector_logging_enable_sip_logs
}
