  default     = "10.0.0.0/16"
}

variable "subnet_a_cidr_block" {
  description = "CIDR block for subnet A"
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr_block" {
  description = "CIDR block for subnet B"
  default     = "10.0.2.0/24"
}

variable "cluster_identifier" {
  description = "Identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "node_type" {
  description = "Node type for the Redshift cluster"
  default     = "dc2.large"
}

variable "database_name" {
  description = "Database name for the Redshift cluster"
  default     = "mydb"
}

variable "master_username" {
  description = "Master username for the Redshift cluster"
  default     = "admin"
}

variable "master_password" {
  description = "Master password for the Redshift cluster"
  default     = "SecureP@ssw0rd!"
}

variable "cluster_subnet_group_name" {
  description = "Name of the Redshift subnet group"
  default     = "my-redshift-subnet-group"
}

resource "aws_vpc" "vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = var.subnet_a_cidr_block
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = var.subnet_b_cidr_block
  availability_zone = "us-west-2b"
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier     = var.cluster_identifier
  node_type              = var.node_type
  database_name          = var.database_name
  master_username        = var.master_username
  master_password        = var.master_password
  cluster_subnet_group_name = var.cluster_subnet_group_name
  availability_zone      = "us-west-2a"
  port                   = 5439
  number_of_nodes        = 1
  cluster_type           = "single-node"
  publicly_accessible    = false
  encrypted              = false
  enhanced_vpc_routing   = true
  logging {
    enable = true
    bucket_name = "my-redshift-logs"
    log_exports = ["userlog", "connectionlog"]
  }
  snapshot_copy {
    destination_region = "us-west-2"
    retention_period   = 7
  }
  timeouts {
    create = "30m"
    delete = "30m"
    update = "30m"
  }
}
