```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "website_images_bucket" {
  bucket = "website-images-bucket"
  acl    = "private"

  # Enable static website hosting
  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  # Enable versioning
  versioning {
    enabled = true
  }

  # Enable server-side encryption for objects
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  # Enable object lock for data retention
  object_lock_enabled = true

  # Set up CORS rules to allow cross-origin requests from the website domain
  cors_rule {
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["https://*.example.com"]
    allowed_headers = ["*"]
    max_age_seconds = 3000
  }

  # Set up lifecycle rules to archive and delete objects
  lifecycle_rule {
    id      = "archive-old-images"
    enabled = true
    prefix  = "archive/"
    tags    = {
      archive = "true"
    }
    abort_incomplete_multipart_upload_days = 7
  }

  lifecycle_rule {
    id      = "delete-expired-images"
    enabled = true
    prefix  = "expired/"
    tags    = {
      expired = "true"
    }
    expiration {
      days = 30
    }
  }

  # Set up logging to track access to the bucket
  logging {
    target_bucket = "website-images-logs"
    target_prefix = "logs/"
  }

  # Set up tags for resource management
  tags = {
    Environment = "production"
    Purpose    = "Website Images"
  }
}
```

