    rule {
      object_ownership = "BucketOwnerPreferred"
    }
  }

  # Optional: Add CORS configuration if needed
  cors_rule {
    allowed_methods = ["GET", "PUT", "POST"]
    allowed_origins = ["*"]
  }

  # Optional: Add lifecycle rules if needed
  lifecycle_rule {
    enabled = true
    id      = "example-lifecycle-rule"
    prefix  = "logs/"
    tags    = {
      Environment = "example"
    }
    abort_incomplete_multipart_upload_days = 7
  }

  # Optional: Add server-side encryption configuration
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  # Optional: Add tags for resource management
  tags = {
    Environment = "example"
    Purpose    = "storage"
  }
}
