provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "code_build_output_bucket" {
  bucket = "code-build-output-bucket"
  acl    = "private"

  # Enable versioning
  versioning {
    enabled = true
  }

  # Enable server-side encryption
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  # Set up logging (optional but recommended for monitoring)
  logging {
    target_bucket = aws_s3_bucket.code_build_output_bucket.bucket
    target_prefix = "logs/"
  }

  # Set up lifecycle rules (optional but recommended for cleanup)
  lifecycle_rule {
    id      = "DeleteExpiredArtifacts"
    enabled = true
    prefix  = "artifacts/"
    expiration {
      days = 7
    }
  }
}

resource "aws_codebuild_project" "code_build_project" {
  name = "student-code-build-project"

  # Define the environment for the CodeBuild project
  environment {
    compute_type      = "BUILD_GENERAL1_SMALL"
    image             = "alpine"
    type              = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  # Define the source configuration
  source {
    type           = "GITHUB"
    location       = "github.com/source-location"
    git_clone_depth = 1
  }

  # Define the artifacts configuration
  artifacts {
    type              = "S3"
    location          = aws_s3_bucket.code_build_output_bucket.bucket
    namespace_type    = "MOCK"
    packaging         = "NONE"
    bucket_owner_access = "OVERRIDE"
  }

  # Set the service role for CodeBuild
  service_role = aws_iam_role.code_build_service_role.arn

  # Optional: Set build timeout
  build_timeout = 1800
}

resource "aws_iam_role" "code_build_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "codebuild.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "code_build_service_role_attachment" {
  role       = aws_iam_role.code_build_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRole"
}
