provider "aws" {
  region = "us-east-1"
}

# Create a VPC for the video streaming site
resource "aws_vpc" "vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "default"
}

# Create a public subnet within the VPC
resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-east-1a"
}

# Create a private subnet within the VPC
resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-east-1b"
}

# Create a security group for web servers
resource "aws_security_group" "web_server_security_group" {
  vpc_id = aws_vpc.vpc.id
  name   = "web-server-sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a Route53 zone for the domain
resource "aws_route53_zone" "domain_zone" {
  name = "example.com"
}

# Create a Route53 record to point the domain to the load balancer
resource "aws_route53_record" "domain_record" {
  name    = "example.com"
  type    = "A"
  zone_id = aws_route53_zone.domain_zone.zone_id
  alias {
    evaluate_target_health = false
    name                    = aws_lb.load_balancer.dns_name
    zone_id                 = aws_lb.load_balancer.zone_id
  }
}

# Create a load balancer
resource "aws_lb" "load_balancer" {
  name               = "video-streaming-lb"
  subnets           = [aws_subnet.public_subnet.id]
  security_groups   = [aws_security_group.web_server_security_group.id]
  internal          = false
  idle_timeout      = 60
  enable_deletion_protection = false
  load_balancer_type = "application"

  access_logs {
    bucket = "terraform-example-bucket"
    prefix = "logs/load-balancer"
    enabled = true
  }

  subnet_mapping {
    subnet_id = aws_subnet.public_subnet.id
  }
}

# Create a target group for the load balancer
resource "aws_lb_target_group" "target_group" {
  name        = "video-streaming-tg"
  port        = 80
  protocol    = "http"
  vpc_id      = aws_vpc.vpc.id
  target_type = "instance"

  health_check {
    path                = "/health"
    protocol            = "HTTP"
    port                = 80
    interval            = 30
    timeout             = 10
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

# Create EC2 instances for the web servers
resource "aws_instance" "web_server" {
  count             = 2
  ami               = "ami-0c55b159cbfafe1f0"
  instance_type     = "t3.micro"
  subnet_id         = aws_subnet.public_subnet.id
  vpc_security_group_ids = [aws_security_group.web_server_security_group.id]
  associate_public_ip_address = true

  tags = {
    Name = "web-server-${count.index + 1}"
  }

  user_data = <<-EOF
    #!/bin/bash
    sudo apt update
    sudo apt install -y nginx
    echo "Welcome to the video streaming server!" > /var/www/html/index.html
    systemctl start nginx
    systemctl enable nginx
  EOF

  provisioner "local-exec" {
    command = "echo 'Web server provisioned'"
  }
}

# Register EC2 instances with the target group
resource "aws_lb_target_group_attachment" "target_group_attachment" {
  count             = aws_instance.web_server.count
  target_group_arn  = aws_lb_target_group.target_group.arn
  target_id         = aws_instance.web_server[count.index].id
  port              = 80
}
