}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "security_group_description" {
  description = "Description for the database security group"
  default     = "Security group for PostgreSQL database access"
}

variable "db_instance_class" {
  description = "Instance class for the PostgreSQL database"
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage for the PostgreSQL database"
  default     = 20
}

variable "db_db_name" {
  description = "Database name for the PostgreSQL instance"
  default     = "postgres"
}

variable "db_master_username" {
  description = "Master username for the PostgreSQL database"
  default     = "admin"
}

variable "db_master_password" {
  description = "Master password for the PostgreSQL database"
  default     = "securepassword123"
}

resource "aws_vpc" "vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = var.public_subnet_cidr
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
}

resource "aws_security_group" "database_security_group" {
  name        = "database-security-group"
  description = var.security_group_description
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "postgresql_instance" {
  instance_class         = var.db_instance_class
  allocated_storage     = var.db_allocated_storage
  engine                 = "postgres"
  engine_version         = "14.5"
  db_name                = var.db_db_name
  master_username        = var.db_master_username
  master_password        = var.db_master_password
  vpc_security_group_ids = [aws_security_group.database_security_group.id]
  db_subnet_group_name   = aws_db_subnet_group.db_subnet_group.name
  skip_final_snapshot    = true
  backup_retention_period = 7
  backup_window          = "07:00-09:00"
  storage_type           = "gp2"
  storage_encrypted      = true
  copy_tags_to_snapshot  = true
  auto_minor_version_upgrade = true
  allow_major_version_upgrade = false
  deletion_protection     = false

  timeouts {
    create = "30m"
    update = "30m"
    delete = "30m"
  }
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.public_subnet.id]
}
