  skip_final_snapshot          = true
  db_subnet_group_name         = aws_db_subnet_group.airbyte_db_subnet_group.name
  vpc_security_group_ids       = [aws_security_group.airbyte_db_sg.id]
  storage_type                 = "gp2"
  deletion_protection           = false
  copy_tags_to_snapshot        = true
  tags = {
    Name = "airbyte-postgresql-instance"
  }
  timeouts {
    create = "30m"
    delete = "30m"
  }
}

resource "aws_db_subnet_group" "airbyte_db_subnet_group" {
  name       = "airbyte-postgresql-subnet-group"
  subnet_ids = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
  tags = {
    Name = "airbyte-postgresql-subnet-group"
  }
}

resource "aws_security_group" "airbyte_db_sg" {
  name        = "airbyte-postgresql-sg"
  description = "Allow access to PostgreSQL instance for Airbyte connector test cases"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    description = "Allow access from Airbyte connector test cases"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "airbyte-postgresql-sg"
  }
}
