}

variable "rds_allocated_storage" {
  description = "Allocated storage for the RDS instance in GB"
  default     = 20
}

variable "rds_db_name" {
  description = "Database name for the RDS instance"
  default     = "mydb"
}

variable "rds_db_username" {
  description = "Database username for the RDS instance"
  default     = "admin"
}

variable "rds_db_password" {
  description = "Database password for the RDS instance"
  default     = "securepassword"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "subnet_public_az1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_public_az1_cidr
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "subnet_public_az2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_public_az2_cidr
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "security_group_db_access" {
  vpc_id        = aws_vpc.main_vpc.id
  description   = var.security_group_description
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "rds_instance" {
  instance_class                = var.rds_instance_class
  allocated_storage            = var.rds_allocated_storage
  engine                        = "mysql5.7"
  engine_version               = "5.7.39"
