```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

variable "instance_class" {
  description = "Instance class for the PostgreSQL database"
  default     = "db.t3.micro"
}

variable "allocated_storage" {
  description = "Allocated storage in GB for the PostgreSQL database"
  default     = 20
}

variable "engine_version" {
  description = "Engine version for the PostgreSQL database"
  default     = "14.8"
}

variable "db_name" {
  description = "Name of the PostgreSQL database"
  default     = "postgres_db"
}

variable "iam_role_name" {
  description = "Name of the IAM role for the PostgreSQL database"
  default     = "postgres_db_role"
}

variable "iam_policy_arn" {
  description = "ARN of the IAM policy to attach to the role"
  default     = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

resource "aws_vpc" "vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = var.subnet_cidr
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_iam_role" "iam_role" {
  name = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect  = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action   = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "iam_role_policy_attachment" {
  role       = aws_iam_role.iam_role.name
  policy_arn = var.iam_policy_arn
}

resource "aws_db_instance" "postgres_instance" {
  instance_class          = var.instance_class
  allocated_storage      = var.allocated_storage
  engine                  = "postgres"
  engine_version          = var.engine_version
  db_name                 = var.db_name
  vpc_security_group_ids  = [aws_db_instance.postgres_instance.vpc_security_group_id]
  db_subnet_group_name    = aws_db_instance.postgres_instance.db_subnet_group_name
  iam_role_arn            = aws_iam_role.iam_role.arn
  skip_final_snapshot     = true

  # Define the subnet group
  db_subnet_group {
    name = "postgres_db_subnet_group"
    subnet_ids = [aws_subnet.subnet.id]
  }

  # Define the VPC security group
  vpc_security_group {
    name = "postgres_db_security_group"
    description = "Security group for PostgreSQL database"
    ingress {
      description = "Allow SSH access"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
    ingress {
      description = "Allow PostgreSQL access"
      from_port   = 5432
      to_port     = 5432
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
    egress {
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }

  timeouts {
    create = "30m"
    delete = "30m"
  }
}
```

