}

variable "subnet_cidr" {
  default = "10.0.1.0/24"
}

variable "availability_zone" {
  default = "us-west-2a"
}

variable "db_instance_class" {
  default = "db.t3.micro"
}

variable "db_engine_version" {
  default = "15.4"
}

variable "db_allocated_storage" {
  default = 20
}

variable "db_backup_retention_period" {
  default = 5
}

variable "db_backup_window" {
  default = "03:00-06:00"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "default"
}

resource "aws_subnet" "main_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr
  availability_zone = var.availability_zone
  map_public_ip_on_launch = true
}

resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main_vpc.id
}

resource "aws_route_table" "main_route_table" {
  vpc_id = aws_vpc.main_vpc.id
}

resource "aws_route" "main_route" {
  route_table_id         = aws_route_table.main_route_table.id
  gateway_id             = aws_internet_gateway.main_igw.id
  destination_cidr_block = "0.0.0.0/0"
}

resource "aws_db_parameter_group" "main_db_parameter_group" {
  family = "postgres15"
  name   = "main_db_parameter_group"
  description = "Custom parameter group for PostgreSQL instance"

  parameter {
    name  = "max_connections"
    value = "100"
    apply_method = "pending-reboot"
  }
}

resource "aws_db_subnet_group" "main_db_subnet_group" {
  name       = "main_db_subnet_group"
  subnet_ids = [aws_subnet.main_subnet.id]
  description = "Subnet group for PostgreSQL database"
}

resource "aws_db_instance" "main_db_instance" {
  allocated_storage        = var.db_allocated_storage
  engine                   = "postgres"
  engine_version           = var.db_engine_version
  instance_class           = var.db_instance_class
  db_name                  = "mydatabase"
  backup_retention_period  = var.db_backup_retention_period
  backup_window            = var.db_backup_window
  db_subnet_group_name     = aws_db_subnet_group.main_db_subnet_group.name
  parameter_group_name     = aws_db_parameter_group.main_db_parameter_group.name
  vpc_security_group_ids   = ["${aws_vpc.main_vpc.default_security_group_id}"]
  skip_final_snapshot      = true
  storage_type             = "gp2"
  deletion_protection       = false
}
