}

resource "aws_s3_bucket" "long_term_data_backup_bucket" {
  bucket = "long-term-data-backup-bucket"
  acl    = "private"

  # Enable versioning for data protection
  versioning {
    enabled = true
  }

  # Enable object lock for legal holds and retention
  object_lock_enabled = true

  # Lifecycle policy for long-term storage (e.g., transition to Glacier after 30 days)
  lifecycle_rule {
    id      = "transition-to-glacier"
    enabled = true
    prefix  = ""
    transition {
      days = 30
      storage_class = "GLACIER"
    }
  }

  # Enable server-side encryption with AWS KMS
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "aws:kms"
      }
    }
  }

  # CORS configuration to allow cross-origin requests (if needed)
  cors_rule {
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    allowed_headers = ["*"]
    max_age_seconds = 3000
  }

  # Tags for resource organization
  tags = {
    Environment = "production"
    Purpose    = "LongTermDataBackup"
  }
}
