  acl    = "private"

  cors_rule {
    allowed_methods = ["PUT", "POST", "GET", "DELETE"]
    allowed_origins = ["*"]
  }

  lifecycle_rule {
    enabled = true
    id      = "default"
    prefix  = ""
  }

  tags = {
    Terraform = "true"
    Environment = "production"
  }
}

resource "aws_s3_bucket_versioning" "glacier_vault_versioning" {
