```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the Network Load Balancer will be created."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs to use for the Network Load Balancer."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "target_group_name" {
  description = "The name of the target group."
  default     = "nlb-target-group"
}

variable "listener_port" {
  description = "The port for the TCP listener."
  default     = 80
}

variable "listener_rule_action" {
  description = "The action for the listener rule (e.g., forward)."
  default     = "forward"
}

variable "target_group_arn" {
  description = "The ARN of the target group."
  default     = "arn:aws:elasticloadbalancing:us-west-2:123456789012:targetgroup/nlb-target-group/1234567890123456"
}

resource "aws_network_load_balancer" "nlb_frontend" {
  name               = "nlb-frontend"
  subnet_ids         = var.subnet_ids
  vpc_id             = var.vpc_id
  ip_address_type    = "ipv4"
  depends_on         = []
}

resource "aws_network_load_balancer_listener" "nlb_listener_tcp" {
  load_balancer_arn = aws_network_load_balancer.nlb_frontend.arn
  port              = var.listener_port
  protocol          = "tcp"
  depends_on        = [aws_network_load_balancer.nlb_frontend]
}

resource "aws_network_load_balancer_listener_rule" "nlb_listener_rule" {
  listener_arn      = aws_network_load_balancer_listener.nlb_listener_tcp.arn
  action {
    type             = var.listener_rule_action
    target_group_arn = var.target_group_arn
  }
  depends_on        = [aws_network_load_balancer.nlb_frontend, aws_network_load_balancer_listener.nlb_listener_tcp]
}

resource "aws_network_load_balancer_target_group" "nlb_target_group" {
  name                = var.target_group_name
  port                = 80
  protocol            = "tcp"
  vpc_id              = var.vpc_id
  health_check {
    path                = "/"
    protocol            = "tcp"
    port                = 80
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 3
  }
