  role       = aws_iam_role.lb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonCognitoPowerUser"
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = 80
  protocol          = "http"

  default_action {
    type = "forward"
    target_group_arn = "arn:aws:elasticloadbalancing:us-west-2:123456789012:targetgroup/my-target-group/1234567890123456"
  }
}

resource "aws_lb_listener_rule" "authenticate_cognito_rule" {
  listener_arn = aws_lb_listener.http_listener.arn
  priority     = 100

  action {
    type = "authenticate-cognito"
    authenticate_cognito {
      user_pool_arn    = var.cognito_user_pool_arn
      user_pool_client_id = var.cognito_client_id
    }
  }

  condition {
    host_header {
      values = ["example.com"]
    }
  }
}
