provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the load balancer will be created."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the load balancer."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "oidc_provider_arn" {
  description = "The ARN of the OIDC provider to use for authentication."
  default     = "arn:aws:iam::123456789012:oidc-provider/example.com"
}

variable "oidc_role_name" {
  description = "The name of the IAM role for OIDC authentication."
  default     = "OIDCAuthRole"
}

variable "oidc_role_policy_arn" {
  description = "The ARN of the IAM policy to attach to the OIDC role."
  default     = "arn:aws:iam::123456789012:policy/OIDCAuthPolicy"
}

resource "aws_lb" "load_balancer" {
  name               = "oidc-auth-load-balancer"
  subnet_ids         = var.subnet_ids
  vpc_id             = var.vpc_id
  internal           = false
  idle_timeout       = 60
  enable_deletion_protection = true
  load_balancer_type = "application"

  access_logs {
    bucket = "terraform-access-logs"
    enabled = true
    prefix = "load-balancer-logs"
  }

  tags = {
    Environment = "production"
    Project     = "oidc-auth"
  }
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = 80
  protocol          = "http"

  default_action {
    type = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }

