    path                = "/"
    protocol            = "http"
    port                = 80
    interval            = 30
    timeout             = 10
    healthy_threshold   = 5
    unhealthy_threshold = 3
  }

  tags = {
    Environment = "production"
    Project     = "oidc-auth"
  }
}

resource "aws_lb_listener_rule" "auth_oidc_rule" {
  listener_arn = aws_lb_listener.http_listener.arn
  priority     = 100

  action {
