provider "aws" {
  region = "us-west-2"
}

variable "rds_cluster_identifier" {
  description = "The identifier for the RDS cluster"
  default     = "my-rds-cluster"
}

variable "rds_cluster_instance_identifier" {
  description = "The identifier for the RDS cluster instance"
  default     = "my-rds-cluster-instance"
}

variable "rds_db_instance_class" {
  description = "The instance class for the RDS cluster instance"
  default     = "db.t3.micro"
}

variable "rds_engine" {
  description = "The engine for the RDS cluster"
  default     = "aurora"
}

variable "rds_allocated_storage" {
  description = "The allocated storage for the RDS cluster"
  default     = 20
}

variable "rds_availability_zones" {
  description = "The availability zones for the RDS cluster"
  default     = ["us-west-2a", "us-west-2b"]
}

variable "iam_role_name" {
  description = "The name of the IAM role for RDS"
  default     = "rds-iam-role"
}

variable "iam_role_policy_arn" {
  description = "The ARN of the IAM policy to attach to the role"
  default     = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

resource "aws_iam_role" "rds_iam_role" {
  name = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_role_attachment" {
  role       = aws_iam_role.rds_iam_role.name
  policy_arn = var.iam_role_policy_arn
}

resource "aws_rds_cluster" "rds_cluster" {
  cluster_identifier      = var.rds_cluster_identifier
  engine                  = var.rds_engine
  allocated_storage      = var.rds_allocated_storage
  availability_zones      = var.rds_availability_zones
  db_cluster_parameter_group_name = "default.aurora-postgresql12"
  engine_version          = "12.11"
  scaling_configuration {
    auto_pause              = true
    max_capacity            = 2
    min_capacity            = 1
    seconds_before_timeout  = 300
    seconds_until_auto_pause = 300
    timeout_action          = "pause"
  }
  timeouts {
    create = "30m"
    delete = "30m"
    update = "30m"
  }
}

resource "aws_rds_cluster_instance" "rds_cluster_instance" {
  cluster_identifier      = var.rds_cluster_identifier
  instance_class          = var.rds_db_instance_class
  engine                  = var.rds_engine
  db_subnet_group_name    = "default"
  monitoring_interval     = 60
  copy_tags_to_snapshot   = true
  tags = {
    Environment = "production"
  }
  timeouts {
    create = "30m"
    delete = "30m"
    update = "30m"
  }
}
