provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "backup_bucket" {
  bucket = "database-backups-terraform"
  acl    = "private"

  # Enable versioning to support restore operations
  versioning {
    enabled = true
  }

  # Set up a policy to allow the DB instance to access the bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { AWS = "arn:aws:iam::${aws_db_instance.database_instance.arn}:root" }
      Action = [
        "s3:GetObject",
        "s3:ListBucket"
      ]
      Resource = [
        "arn:aws:s3:::${aws_s3_bucket.backup_bucket.bucket}",
        "arn:aws:s3:::${aws_s3_bucket.backup_bucket.bucket}/*"
      ]
    }]
  })

  tags = {
    Terraform = "true"
    Environment = "production"
  }
}

resource "aws_db_instance" "database_instance" {
  instance_class           = "db.t3.micro"
  allocated_storage        = 20
  engine                   = "mysql"
  engine_version           = "5.7"
  backup_retention_period  = 7
  backup_window           = "07:00-09:00"
  skip_final_snapshot      = true
  storage_type             = "gp2"
  db_name                  = "mydatabase"
  vpc_security_group_ids   = ["${aws_db_instance.database_instance.vpc_security_group_id}"]
  s3_import {
    bucket_name      = aws_s3_bucket.backup_bucket.bucket
    bucket_prefix    = "backups"
    source_engine    = "mysql"
    source_engine_version = "5.7"
    ingestion_role   = aws_iam_role.restore_role.arn
  }

  # Create an IAM role for the DB instance to access S3
  custom_iam_instance_profile = aws_iam_instance_profile.restore_instance_profile.name
}

resource "aws_iam_role" "restore_role" {
  name = "db-restore-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "restore_role_policy" {
  name = "db-restore-policy"
  role = aws_iam_role.restore_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:ListBucket"
      ]
      Resource = [
        "arn:aws:s3:::${aws_s3_bucket.backup_bucket.bucket}",
        "arn:aws:s3:::${aws_s3_bucket.backup_bucket.bucket}/*"
      ]
    }]
  })
}

resource "aws_iam_instance_profile" "restore_instance_profile" {
  name = "db-restore-instance-profile"
  role = aws_iam_role.restore_role.id
}
```

