provider "aws" {
  region = "us-west-2"
}

resource "aws_kms_key" "default_kms_key" {
  description = "Default KMS key for encrypting secrets"
  key_usage   = "ENCRYPT_DECRYPT"
  key_rotation_enabled = true
}

resource "aws_secrets_manager_secret" "secret_for_master_password" {
  name = "master-password-secret"
  recovery_window_in_days = 7

  rotation {
    automated = true
    schedule_expression = "rate(3600 hours)"
  }

  tags = {
    Environment = "Production"
    Purpose     = "Database Master Password"
  }
}

resource "aws_db_instance" "database_instance" {
  allocated_storage       = 20
  engine                  = "mysql"
  engine_version          = "8.0.33"
  instance_class          = "db.t3.micro"
  master_username         = "admin"
  master_password        = aws_secrets_manager_secret.secret_for_master_password.arn
  backup_retention_period = 7
  skip_final_snapshot     = true
  deletion_protection     = true

  # Optional attributes
  allow_major_version_upgrade = false
  auto_minor_version_upgrade  = true
  copy_tags_to_snapshot       = true
  db_subnet_group_name        = "default"
  storage_type               = "gp2"
  timeout_seconds             = 3600

  # Nested blocks
  timeouts {
    create = "30m"
    update = "30m"
    delete = "30m"
  }
}
